	-- ["{item:10498} to 210"] = "{item:10498} até 210",
	-- ["{item:10505} is yellow at 175 (yellow 175, green 185, grey 195): about 31 crafts to 191. Each takes 2 {item:7912}. Two {item:7912} a craft (Mithril Deposits). Make plenty: the triggers, slugs and Gyro-Shot all use it."] = "{item:10505} é amarelo em 175 (amarelo 175, verde 185, cinza 195): cerca de 31 criações até 191. Cada uma usa 2 {item:7912}. Duas {item:7912} por criação (Depósitos de Mithril). Faça bastante: os gatilhos, as balas e os cartuchos giroscópicos usam.",
	-- ["{item:10505} to 191"] = "{item:10505} até 191",
	-- ["{item:10512} is yellow at 210 (yellow 210, green 230, grey 250): about 19 crafts to 225. Each takes 1 {item:3860} and 1 {item:10505} and makes 200. Use the 19 {item:10505} you made earlier; the counts above leave them out. One {item:3860} and one {item:10505} a craft; hunters buy the slugs. Needs an anvil nearby. {skill:202} 225 is a Legacy System milestone."] = "{item:10512} é amarelo em 210 (amarelo 210, verde 230, cinza 250): cerca de 19 criações até 225. Cada uma usa 1 {item:3860} e 1 {item:10505} e produz 200. Use as 19 {item:10505} que você fez antes; as contagens acima não as incluem. Uma {item:3860} e um {item:10505} por criação; caçadores compram as balas. Precisa de uma bigorna por perto. {skill:202} 225 é um marco do Sistema de Legado.",
	-- ["{item:10512} is yellow at 225 (yellow 210, green 230, grey 250): about 62 crafts to 245. Each takes 1 {item:3860} and 1 {item:10505} and makes 200. Make the 50 {item:10505} first. Use the 12 {item:10505} you made earlier; the counts above leave them out. One {item:3860} and one {item:10505} a craft; hunters buy the slugs. Needs an anvil nearby."] = "{item:10512} é amarelo em 225 (amarelo 210, verde 230, cinza 250): cerca de 62 criações até 245. Cada uma usa 1 {item:3860} e 1 {item:10505} e produz 200. Faça primeiro as 50 {item:10505}. Use as 12 {item:10505} que você fez antes; as contagens acima não as incluem. Uma {item:3860} e um {item:10505} por criação; caçadores compram as balas. Precisa de uma bigorna por perto.",
	-- ["{item:10512} is yellow at 225 (yellow 210, green 230, grey 250): about 62 crafts to 245. Each takes 1 {item:3860} and 1 {item:10505} and makes 200. Make the 50 {item:10505} first. Use the 12 {item:10505} you made earlier; the counts above leave them out. One {item:3860} and one {item:10505} a craft; hunters buy the slugs. Needs an anvil nearby. If you got here without learning {item:10505} and {item:10512}, learn them now: an earlier step teaches them."] = "{item:10512} está amarelo em 225 (amarelo 210, verde 230, cinza 250): cerca de 62 produções até 245. Cada uma leva 1 {item:3860} e 1 {item:10505} e faz 200. Faça primeiro os 50 {item:10505}. Use os 12 {item:10505} que você fez antes; as quantidades acima os deixam de fora. Um {item:3860} e um {item:10505} por produção; caçadores compram as balas. Precisa de uma bigorna por perto. Se chegou aqui sem aprender {item:10505} e {item:10512}, aprenda agora: uma etapa anterior ensina.",
	-- ["{item:10512} to 225"] = "{item:10512} até 225",
	-- ["{item:10512} to 245"] = "{item:10512} até 245",
	-- ["{item:10513} is yellow at 245 (yellow 245, green 265, grey 285): about 28 crafts to 265. Each takes 2 {item:3860} and 2 {item:10505} and makes 200. Make the 56 {item:10505} first. Two Mithril Bars and two {item:10505} a craft. Needs an anvil nearby."] = "{item:10513} é amarelo em 245 (amarelo 245, verde 265, cinza 285): cerca de 28 criações até 265. Cada uma usa 2 {item:3860} e 2 {item:10505} e produz 200. Faça primeiro as 56 {item:10505}. Duas Barras de Mithril e dois {item:10505} por criação. Precisa de uma bigorna por perto.",
	-- ["{item:10513} is yellow at 245 (yellow 245, green 265, grey 285): about 28 crafts to 265. Each takes 2 {item:3860} and 2 {item:10505} and makes 200. Make the 56 {item:10505} first. Two Mithril Bars and two {item:10505} a craft. Needs an anvil nearby. If you got here without learning {item:10505}, learn it now: an earlier step teaches it."] = "{item:10513} está amarelo em 245 (amarelo 245, verde 265, cinza 285): cerca de 28 produções até 265. Cada uma leva 2 {item:3860} e 2 {item:10505} e faz 200. Faça primeiro os 56 {item:10505}. Duas barras de mithril e dois {item:10505} por produção. Precisa de uma bigorna por perto. Se chegou aqui sem aprender {item:10505}, aprenda agora: uma etapa anterior ensina.",
	-- ["{item:10513} to 264"] = "{item:10513} até 264",
